import { Component, Input, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { AuthService } from 'src/app/service/auth.service';
import { CompanyService } from 'src/app/service/company/company.service';
import { JobseekerService } from 'src/app/service/jobseeker/jobseeker.service';

/**
 * Single reusable app header.
 *
 * variant:
 *  - 'guest'   : public pages (landing, jobs, companies, 404, public company profile).
 *                Shows login/signup, or the user's avatar if they happen to be logged in.
 *  - 'company' : authenticated company pages (dashboard, post job, manage jobs, applicants...).
 *  - 'seeker'  : authenticated job seeker pages (dashboard, etc).
 *
 * All the "who is logged in / what are their initials" logic that used to be
 * copy-pasted into every page component now lives here, once.
 */
@Component({
  selector: 'app-header',
  templateUrl: './header.component.html',
  styleUrls: ['./header.component.css']
})
export class HeaderComponent implements OnInit {

  @Input() variant: 'guest' | 'company' | 'seeker' = 'guest';

  isLoggedIn = false;
  initials = '';
  displayName = '';
  profileRoute = '/';

  constructor(
    private authService: AuthService,
    private companyService: CompanyService,
    private jobseekerService: JobseekerService,
    private router: Router
  ) {}

  ngOnInit(): void {
    if (this.variant === 'company') {
      this.isLoggedIn = true;
      this.profileRoute = 'company/company-dashboard';
      this.loadCompanyIdentity(Number(localStorage.getItem('id')));
      return;
    }

    if (this.variant === 'seeker') {
      this.isLoggedIn = true;
      this.profileRoute = 'seeker/jobseeker-dashboard';
      this.loadSeekerIdentity(Number(localStorage.getItem('id')));
      return;
    }

    // guest variant: might still be logged in (e.g. landing page, public company profile)
    this.isLoggedIn = this.authService.isLoggedIn();

    if (!this.isLoggedIn) {
      return;
    }

    const role = localStorage.getItem('role');
    const id = Number(localStorage.getItem('id'));

    if (role === 'COMPANY') {
      this.profileRoute = '../company-dashboard';
      this.loadCompanyIdentity(id);
    } else {
      this.profileRoute = '../jobseeker-dashboard';
      this.loadSeekerIdentity(id);
    }
  }

  private loadCompanyIdentity(id: number): void {
    this.companyService.getCompanyById(id).subscribe({
      next: (company) => {
        this.displayName = company?.companyName ?? '';
        this.initials = this.toInitials(this.displayName);
      },
      error: (err) => console.error(err)
    });
  }

  private loadSeekerIdentity(id: number): void {
    this.jobseekerService.getJobSeekerById(id).subscribe({
      next: (seeker) => {
        this.displayName = `${seeker?.firstName ?? ''} ${seeker?.lastName ?? ''}`.trim();
        this.initials = this.toInitials(this.displayName);
      },
      error: (err) => console.error(err)
    });
  }

  private toInitials(name: string): string {
    return name
      .split(' ')
      .filter(Boolean)
      .map(part => part.charAt(0))
      .join('')
      .substring(0, 2)
      .toUpperCase();
  }

  logout(): void {
    this.authService.logout();
    this.router.navigate(['/']);
  }
}
<header class="topnav" [class.app]="variant !== 'guest'">
  <div class="wrap">

    <a routerLink="/" class="brand"><span class="brand-dot"></span>HireHub</a>

    <!-- Guest nav -->
    <nav class="nav-links" *ngIf="variant === 'guest'">
      <a routerLink="/job/all-jobs">Find Jobs</a>
      <a routerLink="/company/all-companies">Companies</a>
    </nav>

    <!-- Company nav -->
    <nav class="nav-links app-links" *ngIf="variant === 'company'">
      <a routerLink="/company/company-dashboard" routerLinkActive="active">Dashboard</a>
      <a routerLink="/company/company-post-job" routerLinkActive="active">Post a Job</a>
      <a routerLink="/company/company-manage-jobs" routerLinkActive="active">Manage Jobs</a>
      <a routerLink="/company/company-applicants" routerLinkActive="active">Applicants</a>
      <a routerLink="/company/profile-company" routerLinkActive="active">Company Profile</a>
    </nav>

    <!-- Seeker nav -->
    <nav class="nav-links app-links" *ngIf="variant === 'seeker'">
      <a routerLink="/seeker/jobseeker-dashboard" routerLinkActive="active">Dashboard</a>
      <a routerLink="/job/all-jobs" routerLinkActive="active">Find Jobs</a>
      <a routerLink="/application/jobseeker-applications" routerLinkActive="active">Applications</a>
      <a routerLink="/job/saved-jobs" routerLinkActive="active">Saved</a>
      <a routerLink="../profile-jobseeker" routerLinkActive="active">Profile</a>
    </nav>

    <!-- Logged out actions (guest variant only) -->
    <div class="nav-actions" *ngIf="variant === 'guest' && !isLoggedIn">
      <a routerLink="/auth/login" class="btn btn-ghost-dark btn-sm">Log in</a>
      <a routerLink="/auth/register" class="btn btn-primary btn-sm">Sign up</a>
    </div>

    <!-- Logged in actions (any variant) -->
    <div class="nav-actions" *ngIf="isLoggedIn">
      <a class="avatar" [routerLink]="profileRoute" *ngIf="initials">{{ initials }}</a>
      <button class="btn btn-ghost-dark btn-sm" (click)="logout()">Logout</button>
    </div>

  </div>
</header>
